/**
 * Black-Box API Integration Test
 *
 * @target-controller CommunityController (src/main/java/com/tainted/community/web/CommunityController.java)
 * @target-api POST /internal/posts (handler: createPost)
 *
 * 외부 연동: createPost는 CommunityEventPublisher(Kafka, post.created/mood.logged)를 호출하지만
 * Kafka는 HTTP 기반이 아니므로 WireMock 적용 대상이 아니다(Core Principle #4). 발행 여부는
 * 내부 구현이므로 이 블랙박스 테스트에서는 검증하지 않는다.
 *
 * 테스트 플랜 체크리스트(.nimbus/artifacts/test-plan/CommunityService_createPost.md) 대조:
 * - NTC_branch_createPost_1 (Happy Path)   -> NTC_createPost_success_* 3건으로 커버
 * - ATC_code400 (General Bad Request 400)  -> ATC_createPost_malformedJson_returns400 및
 *   VTC_{field}_NULL/EMPTY (MethodArgumentNotValidException -> 400) 로 커버
 *
 * Bean Validation(@NotBlank) 커버리지: CreatePostRequest.userId/title/category/content/nickname
 * 각각에 대해 VTC 표준 rule(NULL, EMPTY 무조건 적용)을 반영한다. moodEmoji는 검증 어노테이션이
 * 없으므로 VTC 대상에서 제외한다.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class PostCreateBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8085");

    private static final String DB_URL = System.getProperty("test.db.url",
            "jdbc:mysql://localhost:3306/community?useSSL=false&allowPublicKeyRetrieval=true&serverTimezone=UTC");
    private static final String DB_USER = System.getProperty("test.db.user", "root");
    private static final String DB_PASSWORD = System.getProperty("test.db.password", "rootpw");

    private static Connection getDbConnection() throws Exception {
        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
    }

    private String testId(TestInfo info) {
        return String.format("T%09d",
                Math.abs(info.getTestMethod().get().getName().hashCode()) % 1_000_000_000);
    }

    private static String readResource(String resourcePath) throws Exception {
        try (InputStream is = PostCreateBlackBoxTest.class.getClassLoader().getResourceAsStream(resourcePath)) {
            if (is == null) {
                throw new IllegalStateException("resource not found: " + resourcePath);
            }
            ByteArrayOutputStream bos = new ByteArrayOutputStream();
            byte[] buffer = new byte[4096];
            int len;
            while ((len = is.read(buffer)) != -1) {
                bos.write(buffer, 0, len);
            }
            return new String(bos.toByteArray(), StandardCharsets.UTF_8);
        }
    }

    private static void executeSqlTemplate(String resourcePath, Map<String, String> params) {
        try (Connection conn = getDbConnection();
             Statement stmt = conn.createStatement()) {
            String sql = readResource(resourcePath);
            for (Map.Entry<String, String> entry : params.entrySet()) {
                sql = sql.replace("${" + entry.getKey() + "}", entry.getValue());
            }
            for (String line : sql.split("\n")) {
                String trimmed = line.trim();
                if (trimmed.startsWith("--") || trimmed.isEmpty()) {
                    continue;
                }
                if (trimmed.endsWith(";")) {
                    trimmed = trimmed.substring(0, trimmed.length() - 1);
                }
                if (!trimmed.isEmpty()) {
                    stmt.execute(trimmed);
                }
            }
        } catch (Exception e) {
            throw new RuntimeException("SQL template execution failed: " + resourcePath, e);
        }
    }

    private static void teardown(String id) {
        Map<String, String> params = new HashMap<String, String>();
        params.put("ID", id);
        executeSqlTemplate("sql/post-create-teardown.sql", params);
    }

    /** value==null -> field omitted from JSON (NULL mutation); value=="" -> field sent empty. */
    private static boolean appendField(StringBuilder sb, String key, String value, boolean first) {
        if (value == null) {
            return first;
        }
        if (!first) {
            sb.append(",");
        }
        sb.append("\"").append(key).append("\":\"").append(value.replace("\"", "\\\"")).append("\"");
        return false;
    }

    private static String createPostBody(String userId, String title, String category, String content,
                                          String moodEmoji, String nickname) {
        StringBuilder sb = new StringBuilder("{");
        boolean first = true;
        first = appendField(sb, "userId", userId, first);
        first = appendField(sb, "title", title, first);
        first = appendField(sb, "category", category, first);
        first = appendField(sb, "content", content, first);
        first = appendField(sb, "moodEmoji", moodEmoji, first);
        first = appendField(sb, "nickname", nickname, first);
        sb.append("}");
        return sb.toString();
    }

    private static Map<String, Object> fetchPostRow(String id) throws Exception {
        try (Connection conn = getDbConnection();
             PreparedStatement ps = conn.prepareStatement(
                     "SELECT user_id, title, category, content, mood_emoji, nickname, likes, created_at "
                             + "FROM post WHERE id = ?")) {
            ps.setString(1, id);
            try (ResultSet rs = ps.executeQuery()) {
                assertTrue(rs.next(), "post row must exist for id=" + id);
                Map<String, Object> row = new HashMap<String, Object>();
                row.put("user_id", rs.getString("user_id"));
                row.put("title", rs.getString("title"));
                row.put("category", rs.getString("category"));
                row.put("content", rs.getString("content"));
                row.put("mood_emoji", rs.getString("mood_emoji"));
                row.put("nickname", rs.getString("nickname"));
                row.put("likes", rs.getInt("likes"));
                row.put("created_at", rs.getTimestamp("created_at"));
                return row;
            }
        }
    }

    @Test
    void NTC_createPost_success_allFieldsIncludingMoodEmoji(TestInfo info) throws Exception {
        String id = testId(info);
