                    .statusCode(201)
                    .body("postId", matchesPattern(
                            "[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}"))
                    .extract().path("postId");

            Map<String, Object> row = fetchPostRow(postId);
            assertEquals(userId, row.get("user_id"));
            assertEquals("Title " + id, row.get("title"));
            assertEquals("career", row.get("category"));
            assertEquals("Content " + id, row.get("content"));
            assertEquals("😀", row.get("mood_emoji"));
            assertEquals("nick-" + id, row.get("nickname"));
            assertEquals(0, row.get("likes"));
        } finally {
            if (postId != null) {
                teardown(postId);
            }
