        String id = testId(info);
        String userId = "user-" + id;
        String postId = null;
        try {
            postId = given().log().all()
                    .baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body(createPostBody(userId, "Daily " + id, "daily",
