/**
 * Black-Box API Integration Test
 *
 * @target-controller CommunityController (src/main/java/com/tainted/community/web/CommunityController.java)
 * @target-api POST /internal/posts/{id}/comments (handler: addComment)
 *
 * 외부 연동: addComment는 CommunityEventPublisher(Kafka, comment.created)를 호출하지만
 * Kafka는 HTTP 기반이 아니므로 WireMock 적용 대상이 아니다(Core Principle #4).
 *
 * 테스트 플랜 체크리스트(.nimbus/artifacts/test-plan/CommunityService_addComment.md) 대조:
 * - NTC_branch_addComment_2 (Happy Path)      -> NTC_addComment_success_* 3건으로 커버
 * - ATC_postId_noData (DB에 postId 없음)       -> ATC_postId_noData 로 커버
 * - ATC_code400 (General Bad Request 400)     -> VTC_author_NULL/EMPTY 등 Bean Validation
 *   실패 케이스(400)로 커버
 *
 * postId는 경로 변수이므로 NULL/EMPTY 변조는 라우팅 계층에서 처리되어 이 핸들러에 도달하지
 * 않는다(PostGetByIdBlackBoxTest와 동일한 사유). 대신 WHITE_SPACE/SPECIAL_CHAR로 대체 커버.
 *
 * CreateCommentRequest.author/role/content 는 모두 @NotBlank 이므로 컨트롤러 진입 전
 * @Valid 검증이 수행된다 — 검증 실패 케이스는 대상 post 존재 여부와 무관하게 400을
 * 반환하므로 별도 post fixture 없이도 검증 가능하다.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class PostCommentCreateBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8085");

    private static final String DB_URL = System.getProperty("test.db.url",
            "jdbc:mysql://localhost:3306/community?useSSL=false&allowPublicKeyRetrieval=true&serverTimezone=UTC");
    private static final String DB_USER = System.getProperty("test.db.user", "root");
    private static final String DB_PASSWORD = System.getProperty("test.db.password", "rootpw");

    private static Connection getDbConnection() throws Exception {
        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
    }

    private String testId(TestInfo info) {
        return String.format("T%09d",
                Math.abs(info.getTestMethod().get().getName().hashCode()) % 1_000_000_000);
    }

    private static String readResource(String resourcePath) throws Exception {
        try (InputStream is = PostCommentCreateBlackBoxTest.class.getClassLoader()
                .getResourceAsStream(resourcePath)) {
            if (is == null) {
                throw new IllegalStateException("resource not found: " + resourcePath);
            }
            ByteArrayOutputStream bos = new ByteArrayOutputStream();
            byte[] buffer = new byte[4096];
            int len;
            while ((len = is.read(buffer)) != -1) {
                bos.write(buffer, 0, len);
            }
            return new String(bos.toByteArray(), StandardCharsets.UTF_8);
        }
    }

    private static void executeSqlTemplate(String resourcePath, Map<String, String> params) {
        try (Connection conn = getDbConnection();
             Statement stmt = conn.createStatement()) {
            String sql = readResource(resourcePath);
            for (Map.Entry<String, String> entry : params.entrySet()) {
                sql = sql.replace("${" + entry.getKey() + "}", entry.getValue());
            }
            for (String line : sql.split("\n")) {
                String trimmed = line.trim();
                if (trimmed.startsWith("--") || trimmed.isEmpty()) {
                    continue;
                }
                if (trimmed.endsWith(";")) {
                    trimmed = trimmed.substring(0, trimmed.length() - 1);
                }
                if (!trimmed.isEmpty()) {
                    stmt.execute(trimmed);
                }
            }
        } catch (Exception e) {
            throw new RuntimeException("SQL template execution failed: " + resourcePath, e);
        }
    }

    private static Map<String, String> postParams(String id, String userId, String title, String category,
                                                    String content, String moodEmojiSql, String nickname,
                                                    int likes, String createdAt) {
        Map<String, String> params = new HashMap<String, String>();
        params.put("ID", id);
        params.put("USER_ID", userId);
        params.put("TITLE", title);
        params.put("CATEGORY", category);
        params.put("CONTENT", content);
        params.put("MOOD_EMOJI_SQL", moodEmojiSql);
        params.put("NICKNAME", nickname);
        params.put("LIKES", String.valueOf(likes));
        params.put("CREATED_AT", createdAt);
        return params;
    }

    private static void insertPost(String id) {
        Map<String, String> params = postParams(id, "user-" + id, "Title " + id, "career",
                "content " + id, "NULL", "nick-" + id, 0, "2024-05-01 10:00:00");
        executeSqlTemplate("sql/post-comment-create-teardown.sql", params);
        executeSqlTemplate("sql/post-comment-create-setup.sql", params);
    }

    private static void insertExistingComment(String postId, String commentId, String author, String role,
                                               String content) {
        Map<String, String> params = new HashMap<String, String>();
        params.put("ID", postId);
        params.put("COMMENT_ID", commentId);
        params.put("EXISTING_AUTHOR", author);
        params.put("EXISTING_ROLE", role);
        params.put("EXISTING_CONTENT", content);
        params.put("EXISTING_CREATED_AT", "2024-05-01 11:00:00");
        executeSqlTemplate("sql/post-comment-create-existing-comment-setup.sql", params);
    }

    private static void teardown(String postId) {
        Map<String, String> params = new HashMap<String, String>();
        params.put("ID", postId);
        executeSqlTemplate("sql/post-comment-create-teardown.sql", params);
    }

    private static String createCommentBody(String author, String role, String content) {
        StringBuilder sb = new StringBuilder("{");
        boolean first = true;
        first = appendField(sb, "author", author, first);
        first = appendField(sb, "role", role, first);
        appendField(sb, "content", content, first);
        sb.append("}");
        return sb.toString();
    }

    private static boolean appendField(StringBuilder sb, String key, String value, boolean first) {
        if (value == null) {
            return first;
        }
        if (!first) {
            sb.append(",");
        }
        sb.append("\"").append(key).append("\":\"").append(value.replace("\"", "\\\"")).append("\"");
        return false;
    }

    private static int countComments(String postId) throws Exception {
        try (Connection conn = getDbConnection();
             PreparedStatement ps = conn.prepareStatement(
                     "SELECT COUNT(*) FROM comment WHERE post_id = ?")) {
            ps.setString(1, postId);
            try (ResultSet rs = ps.executeQuery()) {
                assertTrue(rs.next());
                return rs.getInt(1);
            }
        }
    }

    private static Map<String, Object> fetchCommentRow(String commentId) throws Exception {
        try (Connection conn = getDbConnection();
             PreparedStatement ps = conn.prepareStatement(
                     "SELECT post_id, author, role, content FROM comment WHERE id = ?")) {
            ps.setString(1, commentId);
            try (ResultSet rs = ps.executeQuery()) {
                assertTrue(rs.next(), "comment row must exist for id=" + commentId);
                Map<String, Object> row = new HashMap<String, Object>();
                row.put("post_id", rs.getString("post_id"));
                row.put("author", rs.getString("author"));
                row.put("role", rs.getString("role"));
                row.put("content", rs.getString("content"));
                return row;
            }
        }
    }

    @Test
    void NTC_addComment_success_savesAllFieldsAndReturnsResponse(TestInfo info) throws Exception {
        String postId = testId(info);
        String commentId = null;
        try {
            insertPost(postId);

            commentId = given().log().all()
                    .baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body(createCommentBody("공감 수현", "empathic", "힘내세요 " + postId))
                .when()
                    .post("/internal/posts/" + postId + "/comments")
                .then().log().all()
                    .statusCode(201)
                    .body("postId", equalTo(postId))
                    .body("role", equalTo("empathic"))
                    .body("commentId", matchesPattern(
                            "[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}"))
                    .extract().path("commentId");

            Map<String, Object> row = fetchCommentRow(commentId);
            assertEquals(postId, row.get("post_id"));
            assertEquals("공감 수현", row.get("author"));
