        params.put("EXISTING_AUTHOR", author);
        params.put("EXISTING_ROLE", role);
        params.put("EXISTING_CONTENT", content);
        params.put("EXISTING_CREATED_AT", "2024-05-01 11:00:00");
        executeSqlTemplate("sql/post-comment-create-existing-comment-setup.sql", params);
    }

    private static void teardown(String postId) {
