        first = appendField(sb, "author", author, first);
        first = appendField(sb, "role", role, first);
        appendField(sb, "content", content, first);
        sb.append("}");
        return sb.toString();
    }

    private static boolean appendField(StringBuilder sb, String key, String value, boolean first) {
        if (value == null) {
            return first;
        }
        if (!first) {
            sb.append(",");
        }
        sb.append("\"").append(key).append("\":\"").append(value.replace("\"", "\\\"")).append("\"");
        return false;
