                return rs.getInt(1);
            }
        }
    }

    private static Map<String, Object> fetchCommentRow(String commentId) throws Exception {
        try (Connection conn = getDbConnection();
             PreparedStatement ps = conn.prepareStatement(
                     "SELECT post_id, author, role, content FROM comment WHERE id = ?")) {
            ps.setString(1, commentId);
            try (ResultSet rs = ps.executeQuery()) {
                assertTrue(rs.next(), "comment row must exist for id=" + commentId);
                Map<String, Object> row = new HashMap<String, Object>();
                row.put("post_id", rs.getString("post_id"));
                row.put("author", rs.getString("author"));
                row.put("role", rs.getString("role"));
                row.put("content", rs.getString("content"));
                return row;
            }
        }
    }

